mapper.update:
UPDATE practice_record
SET is_correct = #{isCorrect}
WHERE id = #{id} AND submitted_at IS NOT NULL AND is_correct IS NULL

mapper.select:
SELECT id, user_id, question_id, is_correct, duration_sec, started_at, submitted_at, practice_date
FROM (
  SELECT ,
         ROW_NUMBER() OVER (PARTITION BY question_id ORDER BY id DESC) AS rn
  FROM practice_record
  WHERE user_id = #{userId}
    AND question_id IN
    #{qid}
    AND is_correct IS NOT NULL
) t
WHERE rn <= #{limit}
ORDER BY question_id, id DESC
